const http = require('http');

const entries = [];

const DEFAULT_LIMIT = 20;
const MAX_LIMIT = 100;

function parsePositiveInt(raw) {
  if (!/^[1-9]\d*$/.test(raw)) return NaN; // 非正整数
  return Number(raw);
}

function sendJson(res, statusCode, payload) {
  res.statusCode = statusCode;
  res.setHeader('content-type', 'application/json');
  res.end(JSON.stringify(payload));
}

const server = http.createServer((req, res) => {
  const url = new URL(req.url, 'http://localhost');

  if (req.method === 'POST' && url.pathname === '/entries') {
    let body = '';
    req.on('data', (c) => { body += c; });
    req.on('end', () => {
      const { amount, note } = JSON.parse(body || '{}');
      entries.push({ id: entries.length + 1, amount, note, ts: Date.now() });
      sendJson(res, 201, { ok: true }); // hmm — POST currently res.end('ok') plain text
    });
    return;
  }

  if (req.method === 'GET' && url.pathname === '/entries') {
    const page = url.searchParams.has('page') ? parsePositiveInt(url.searchParams.get('page')) : 1;
    const limit = url.searchParams.has('limit') ? parsePositiveInt(url.searchParams.get('limit')) : DEFAULT_LIMIT;
    if (Number.isNaN(page) || Number.isNaN(limit)) {
      sendJson(res, 400, { error: 'page and limit must be positive integers' });
      return;
    }
    const pageSize = Math.min(limit, MAX_LIMIT);
    const total = entries.length;
    const totalPages = Math.ceil(total / pageSize);
    const start = (page - 1) * pageSize;
    sendJson(res, 200, {
      entries: entries.slice(start, start + pageSize),
      page,
      pageSize,
      total,
      totalPages,
    });
    return;
  }

  res.statusCode = 404;
  res.end('not found');
});

if (require.main === module) {
  server.listen(3000);
}

module.exports = { server, entries, DEFAULT_LIMIT, MAX_LIMIT };
```

