      entries: entries.slice(start, start + pageSize),
      page,
      pageSize,
      total: entries.length,
      totalPages: Math.ceil(entries.length / pageSize),
    });
    return;
  }

  res.statusCode = 404;
  res.end('not found');
});

if (require.main === module) {
  server.listen(3000);
}

module.exports = { server, DEFAULT_LIMIT, MAX_LIMIT };
